(()=>{
const U='https://fzqpmpgbubpmongodcat.supabase.co',K='eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImZ6cXBtcGdidWJwbW9uZ29kY2F0Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODc5NzI5MzIsImV4cCI6MjEwMzU0ODkzMn0.pLJfo5jpfMNRQCAbKC1dEW_INuBJan_eoyB_hWpChdw';
const headers={'apikey':K,'Authorization':'Bearer '+K,'Content-Type':'application/json'};let visible=true,ready=false;
async function load(){try{const r=await fetch(U+'/rest/v1/rpc/get_plans_visibility',{method:'POST',headers,body:'{}'});const j=await r.json();visible=typeof j==='boolean'?j:(j?.plans_visible??j?.[0]?.plans_visible??true);}catch{}ready=true;apply();mountAdmin();}
function apply(){const box=document.querySelector('.rcp-plans');if(box)box.style.display=visible?'':'none';}
function session(){try{return JSON.parse(sessionStorage.getItem('rc_music_dj_session_v1')||localStorage.getItem('rc_music_dj_session_v1')||'null')}catch{return null}}
function mountAdmin(){if(!ready)return;const root=document.querySelector('div[class*="z-[11000]"]');if(!root||root.querySelector('#rc-plan-visibility'))return;const payment=[...root.querySelectorAll('button')].find(b=>/M[eé]todos de pago/i.test(b.textContent||''));if(!payment)return;const box=document.createElement('div');box.id='rc-plan-visibility';box.style.cssText='margin:8px 0 10px;padding:10px 12px;border:1px solid rgba(0,229,255,.25);border-radius:12px;background:rgba(0,229,255,.06);';const label=document.createElement('label');label.style.cssText='display:flex;align-items:center;gap:9px;cursor:pointer;font-size:12px;font-weight:800;color:#fff;';const input=document.createElement('input');input.type='checkbox';input.checked=visible;input.style.cssText='width:16px;height:16px;accent-color:#00e5ff;cursor:pointer;';const text=document.createElement('span');text.textContent='Mostrar planes en la pantalla de adquisición';label.append(input,text);const msg=document.createElement('p');msg.style.cssText='margin:6px 0 0 25px;font-size:11px;color:rgba(255,255,255,.5);';input.onchange=async()=>{const previous=visible;visible=input.checked;msg.textContent='Guardando…';try{const s=session();if(!s?.token)throw Error();const r=await fetch(U+'/rest/v1/rpc/admin_set_plans_visibility',{method:'POST',headers,body:JSON.stringify({p_token:s.token,p_visible:visible})});if(!r.ok)throw Error();msg.textContent=visible?'Planes visibles.':'Planes ocultos.';apply();}catch{visible=previous;input.checked=previous;msg.textContent='No se pudo guardar la configuración.'}};box.append(label,msg);payment.parentNode?.insertBefore(box,payment.nextSibling);}
new MutationObserver(()=>{apply();mountAdmin()}).observe(document.documentElement,{childList:true,subtree:true});load();
})();